import fs from "node:fs";
import path from "node:path";
import { kitDir } from "./paths";

/*
 * Kit metadata for the library page. Read from packages/kit/docs/kit-meta.json,
 * generated by `npm run kit:docs`, so server code never imports React components.
 */

export type KitProp = { name: string; type: string; def: string; description: string };
export type KitExample = { file: string; narration: string; code: string };
export type KitItem = {
  name: string;
  category: string;
  summary: string;
  useWhen: string[];
  avoidWhen: string[];
  children?: string | null;
  props: KitProp[];
  example: KitExample | null;
};

type RawItem = Omit<KitItem, "example"> & { example: string | null };

function readExample(file: string): KitExample | null {
  try {
    const src = fs.readFileSync(path.join(kitDir(), "examples", file), "utf8");
    const m = /export const narration =\s*"([\s\S]*?)";/.exec(src);
    return { file, narration: m ? m[1] : "", code: src };
  } catch {
    return null;
  }
}

export function kitItems(): KitItem[] {
  try {
    const raw = JSON.parse(fs.readFileSync(path.join(kitDir(), "docs", "kit-meta.json"), "utf8")) as RawItem[];
    return raw.map((r) => ({ ...r, example: r.example ? readExample(r.example) : null }));
  } catch {
    return [];
  }
}

export function kitDocsInfo() {
  try {
    const st = fs.statSync(path.join(kitDir(), "docs", "kit-docs.md"));
    return { bytes: st.size, updatedAt: st.mtime.toISOString() };
  } catch {
    return null;
  }
}
